-- These bytes are pinned from the v0.3.0 serializers, not generated by current
-- writers. Keep fixtures immutable; a format change adds another version dir.
local H = require('tests.support.harness')
local format = require('direct.history.format')
local transaction = require('direct.history.transaction')
local history = require('direct.history.history')
local action = require('direct.action.action')
local register = require('direct.register')
local trash = require('direct.trash')
local trash_metadata = require('direct.trash.metadata')
local lock = require('direct.history.lock')

local fixture_root =
  vim.fs.joinpath(vim.fs.dirname(vim.fs.abspath(debug.getinfo(1, 'S').source:sub(2))), '../fixtures/formats/v0.3.0')

local function fixture(path)
  local full_path = vim.fs.joinpath(fixture_root, path)
  local fd, err = vim.uv.fs_open(full_path, 'r', 0)
  H.assert_not_nil(fd, 'open fixture ' .. path .. ': ' .. tostring(err))
  local stat = vim.uv.fs_fstat(fd)
  H.assert_not_nil(stat, 'stat fixture ' .. path)
  local bytes, read_err = vim.uv.fs_read(fd, stat.size, 0)
  vim.uv.fs_close(fd)
  H.assert_not_nil(bytes, 'read fixture ' .. path .. ': ' .. tostring(read_err))
  return bytes
end

local function write_raw(path, bytes)
  vim.fn.mkdir(vim.fs.dirname(path), 'p')
  local fd, err = vim.uv.fs_open(path, 'w', 384)
  H.assert_not_nil(fd, 'open file for fixture bytes: ' .. tostring(err))
  local written, write_err = vim.uv.fs_write(fd, bytes, 0)
  local closed, close_err = vim.uv.fs_close(fd)
  H.assert_not_nil(written, 'write fixture bytes: ' .. tostring(write_err))
  H.assert_true(closed, 'close fixture file: ' .. tostring(close_err))
end

local function read_raw(path)
  local fd, err = vim.uv.fs_open(path, 'r', 0)
  H.assert_not_nil(fd, 'open persisted file: ' .. tostring(err))
  local stat = vim.uv.fs_fstat(fd)
  H.assert_not_nil(stat, 'stat persisted file')
  local bytes, read_err = vim.uv.fs_read(fd, stat.size, 0)
  vim.uv.fs_close(fd)
  H.assert_not_nil(bytes, 'read persisted file: ' .. tostring(read_err))
  return bytes
end

local function stack_lines(bytes)
  local lines = vim.split(bytes, '\n', { plain = true })
  if lines[#lines] == '' then table.remove(lines) end
  return lines
end

local function history_dir(sb) return vim.fs.joinpath(sb.data_home, 'direct/history') end

H.describe('v0.3.0 persisted-format goldens', function()
  H.it('loads the exact old stacks, including every serialized action kind', function()
    local undo_bytes = fixture('stacks/undo.log')
    local redo_bytes = fixture('stacks/redo.log')
    local undo = format.classify(undo_bytes, true)
    local redo = format.classify(redo_bytes, true)

    H.assert_eq(undo.state, 'current', 'v0.3.0 undo bytes are recognized')
    H.assert_eq(redo.state, 'current', 'v0.3.0 redo bytes are recognized')
    local names = {}
    for index = 2, #undo.lines do
      local parsed = action.deserialize(undo.lines[index])
      H.assert_not_nil(parsed, 'each old action record is readable')
      names[#names + 1] = parsed.name
    end
    H.assert_eq(names, {
      'mv',
      'rm',
      'rmdir',
      'rs',
      'rsdir',
      'touch',
      'mkdir',
      'p',
      'up',
      'g',
      'batch',
    }, 'all v0.3.0 serialized action kinds retain their meaning')

    local sb = H.sandbox()
    local dir = history_dir(sb)
    write_raw(vim.fs.joinpath(dir, 'undo.log'), undo_bytes)
    write_raw(vim.fs.joinpath(dir, 'redo.log'), redo_bytes)
    local state, err = history.preflight()
    H.assert_not_nil(state, 'current readers accept v0.3.0 stacks: ' .. tostring(err))
    H.assert_eq(state.undo_lines, stack_lines(undo_bytes), 'undo state matches the exact fixture lines')
    H.assert_eq(state.redo_lines, stack_lines(redo_bytes), 'redo state matches the exact fixture lines')
    H.assert_eq(read_raw(vim.fs.joinpath(dir, 'undo.log')), undo_bytes, 'reading did not rewrite old undo bytes')
    H.assert_eq(read_raw(vim.fs.joinpath(dir, 'redo.log')), redo_bytes, 'reading did not rewrite old redo bytes')
  end)

  H.it('parses every pinned v0.3.0 journal recovery snapshot semantically', function()
    local expected = {
      ['apply-not-started.json'] = { kind = 'apply', action = 'touch' },
      ['apply-filesystem-complete.json'] = { kind = 'apply', action = 'mv' },
      ['apply-group-staged.json'] = { kind = 'apply', action = 'g', next_step = 2 },
      ['reverse-filesystem-complete.json'] = { kind = 'reverse', action = 'mv', direction = 'undo' },
      ['paste-copy-pending.json'] = { kind = 'paste', action = 'p', pending = true },
      ['paste-copy-complete.json'] = { kind = 'paste', action = 'p', completed = 1 },
      ['unpaste-preflight.json'] = { kind = 'unpaste', action = 'up', phase = 'preflight' },
      ['unpaste-capture.json'] = { kind = 'unpaste', action = 'up', phase = 'capture' },
      ['unpaste-delete.json'] = { kind = 'unpaste', action = 'up', phase = 'delete' },
      ['stack-commit.json'] = { kind = 'stacks' },
    }

    for name, want in pairs(expected) do
      local bytes = fixture('journals/' .. name)
      local parsed = transaction.parse(bytes)
      H.assert_not_nil(parsed, 'current reader accepts v0.3.0 journal ' .. name)
      H.assert_eq(parsed.kind, want.kind, name .. ' keeps its transaction kind')
      if want.action then
        local decoded = action.deserialize(parsed.action)
        H.assert_not_nil(decoded, name .. ' action remains readable')
        H.assert_eq(decoded.name, want.action, name .. ' action is not reinterpreted')
      end
      for _, key in ipairs({ 'direction', 'phase', 'next_step' }) do
        if want[key] ~= nil then H.assert_eq(parsed[key], want[key], name .. ' retains ' .. key) end
      end
      if want.pending then H.assert_not_nil(parsed.pending.src, name .. ' retains pending source') end
      if want.completed then H.assert_eq(#parsed.completed, want.completed, name .. ' retains completed copies') end
    end
  end)

  H.it('reads both old trash sidecars without changing their metadata', function()
    local sb = H.sandbox()
    local dir = vim.fs.joinpath(sb.data_home, 'direct/trash')
    local file_entry = vim.fs.joinpath(dir, 'file-entry')
    local directory_entry = vim.fs.joinpath(dir, 'directory-entry')
    vim.fn.mkdir(dir, 'p')
    write_raw(file_entry, 'payload')
    vim.fn.mkdir(directory_entry, 'p')
    vim.fn.writefile({ 'nested payload' }, vim.fs.joinpath(directory_entry, 'nested.txt'))
    local file_metadata = fixture('trash/file.direct-trash.json')
    local directory_metadata = fixture('trash/directory.direct-trash.json')
    write_raw(trash_metadata.path(file_entry), file_metadata)
    write_raw(trash_metadata.path(directory_entry), directory_metadata)

    local entries = trash.entries()
    local by_id = {}
    for _, entry in ipairs(entries) do
      by_id[entry.id] = entry
    end
    H.assert_eq(by_id['file-entry'].original, '/a47/work/deleted.txt', 'file original path is retained')
    H.assert_eq(by_id['file-entry'].kind, 'file', 'file kind is retained')
    H.assert_eq(by_id['file-entry'].deleted_at, '2026-05-01T10:20:30Z', 'file timestamp is retained')
    H.assert_eq(by_id['directory-entry'].original, '/a47/work/deleted-dir', 'directory original path is retained')
    H.assert_eq(by_id['directory-entry'].kind, 'directory', 'directory kind is retained')
    H.assert_eq(by_id['directory-entry'].deleted_at, '2026-05-02T11:21:31Z', 'directory timestamp is retained')
    H.assert_eq(read_raw(trash_metadata.path(file_entry)), file_metadata, 'file sidecar bytes are unchanged')
    H.assert_eq(
      read_raw(trash_metadata.path(directory_entry)),
      directory_metadata,
      'directory sidecar bytes are unchanged'
    )
  end)

  H.it('reads the old register pointer and copied-entry tree without a manifest', function()
    local sb = H.sandbox()
    local original_pointer = fixture('register/content')
    local fixture_dir = vim.fs.joinpath(fixture_root, 'register')
    local digest = 'dca5a996289cc22c8805f260fc1510221c3bf85d6a617aa94f0af4964f3e7c84'
    local source_path = '/a47/work/source.txt'
    H.assert_eq(
      vim.fn.sha256(source_path),
      digest,
      'digest directory name matches the v0.3.0 sorted-source SHA-256 rule'
    )
    H.assert_eq(
      original_pointer,
      '/a47/data/direct/register/' .. digest .. '\n',
      'fixture pointer targets the digest-named copied-entry directory'
    )

    local content_dir = vim.fs.joinpath(sb.data_home, 'direct/register', digest)
    local pointer = original_pointer:gsub('/a47/data', sb.data_home)
    local pointer_path = vim.fs.joinpath(sb.data_home, 'direct/register/content')
    local fixture_payload_path = vim.fs.joinpath(fixture_dir, digest, 'source.txt')
    local payload = fixture('register/' .. digest .. '/source.txt')
    write_raw(vim.fs.joinpath(content_dir, 'source.txt'), payload)
    write_raw(pointer_path, pointer)

    H.assert_eq(register.content(), pointer:gsub('\n+$', ''), 'old register pointer is readable')
    H.assert_eq(read_raw(pointer_path), pointer, 'reading the pointer preserves its installed bytes')
    H.assert_eq(register.entries(content_dir)[1].name, 'source.txt', 'copied entry is found without a manifest')
    H.assert_eq(
      register.resolve(content_dir, 'source.txt'),
      vim.fs.joinpath(content_dir, 'source.txt'),
      'current resolver uses the old copied-entry tree'
    )
    H.assert_eq(
      read_raw(vim.fs.joinpath(content_dir, 'source.txt')),
      payload,
      'copied entry retains its fixture payload bytes'
    )
    H.assert_true(vim.uv.fs_stat(fixture_payload_path) ~= nil, 'the digest-named golden tree is present')
  end)

  H.it('keeps the v0.3.0 lock file empty while using the current OS lock', function()
    local sb = H.sandbox()
    local path = vim.fs.joinpath(sb.data_home, 'direct', '.direct-history.lock')
    local bytes = fixture('lock/.direct-history.lock')
    H.assert_eq(bytes, '', 'v0.3.0 lock file has no serialized bytes or version marker')
    write_raw(path, bytes)

    H.assert_true(lock.acquire(), 'current lock reader acquires the old persistent lock file')
    H.assert_true(lock.release(), 'current lock reader releases the old lock')
    H.assert_eq(read_raw(path), bytes, 'OS locking does not reinterpret or rewrite lock bytes')
  end)

  H.it('preserves and blocks operations on an unknown old-stack record', function()
    local sb = H.sandbox()
    local dir = history_dir(sb)
    local original = fixture('stacks/undo.log')
    local damaged = original:gsub('"op":"mv"', '"op":"future-mv"', 1)
    local undo_path = vim.fs.joinpath(dir, 'undo.log')
    write_raw(undo_path, damaged)
    write_raw(vim.fs.joinpath(dir, 'redo.log'), fixture('stacks/redo.log'))
    local target = vim.fs.joinpath(sb.root, 'must-not-be-created.txt')

    local state = history.preflight()
    H.assert_nil(state, 'unknown history record blocks preflight')
    local logged = history.log(action.Touch(target))
    H.assert_nil(logged, 'unknown history record blocks new history operations')
    H.assert_eq(read_raw(undo_path), damaged, 'refusal preserves the exact original bytes')
    H.assert_false(vim.uv.fs_stat(target) ~= nil, 'refusal does not partially apply the requested action')
  end)

  H.it('preserves and blocks operations on an unknown journal version', function()
    local sb = H.sandbox()
    local dir = history_dir(sb)
    local original = fixture('journals/apply-not-started.json')
    local unknown = original:gsub('"version":1', '"version":99', 1)
    local journal_path = vim.fs.joinpath(dir, 'transaction.json')
    write_raw(journal_path, unknown)
    local target = vim.fs.joinpath(sb.root, 'must-not-be-created.txt')

    local state = history.preflight()
    H.assert_nil(state, 'unknown journal version blocks preflight')
    local logged = history.log(action.Touch(target))
    H.assert_nil(logged, 'unknown journal version blocks new history operations')
    H.assert_eq(read_raw(journal_path), unknown, 'refusal preserves the exact journal bytes')
    H.assert_false(vim.uv.fs_stat(target) ~= nil, 'refusal never partially applies the requested action')
  end)
end)
